def numpy_to_gsl_matrix(np_array):
    rows, cols = np_array.shape
    gsl_matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix[i, j] = np_array[i, j]
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    np_array = np.empty((gsl_matrix.rows, gsl_matrix.cols), dtype=np.float64)
    for i in range(gsl_matrix.rows):
        for j in range(gsl_matrix.cols):
            np_array[i, j] = gsl_matrix[i, j]
    return np_array

def compute_covariance_matrix(jacobian, epsrel, rows, cols):
    if not load_gsl():
        raise ValueError("GSL library could not be loaded")
    gsl_jacobian = numpy_to_gsl_matrix(jacobian)
    gsl_covariance = GSLMatrix(rows, rows)
    gsl.gsl_multifit_covar(gsl_jacobian.ptr, epsrel, gsl_covariance.ptr)
    return gsl_matrix_to_numpy(gsl_covariance)

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self._matrix = np.empty((rows, cols), dtype=np.float64)

    @property
    def ptr(self):
        return ctypes.c_void_p(id(self))

    def __getitem__(self, key):
        row, col = key
        if not isinstance(row, int) or not isinstance(col, int):
            raise TypeError("Indices must be integers")
        if row < 0 or row >= self.rows or col < 0 or col >= self.cols:
            raise IndexError("Index out of range")
        return self._matrix[row, col]

    def __setitem__(self, key, value):
        row, col = key
        if not isinstance(row, int) or not isinstance(col, int):
            raise TypeError("Indices must be integers")
        if row < 0 or row >= self.rows or col < 0 or col >= self.cols:
            raise IndexError("Index out of range")
        self._matrix[row, col] = value

    def __repr__(self):
        return f"GSLMatrix({self.rows}, {self.cols})"

