gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

class GSLFunction:
    def __init__(self, function):
        self.function = function

    def __call__(self, x):
        return self.function(x)

def integrate_qk51(func, a, b):
    gsl_function = GSLFunction(lambda x: func(x))
    result = gsl.gsl_integration_qk51(&gsl_function, a, b)
    return result

