        if self.gsl is None or self.cblas is None:
            raise ValueError("GSL library not loaded")
        gsl_vector = self.gsl.gsl_vector_alloc(np_array.size)
        for i in range(np_array.size):
            gsl_vector.data[i] = np_array.data[i].real
            gsl_vector.data[i + 1] = np_array.data[i].imag
        return gsl_vector

