        if self.gsl is None or self.cblas is None:
            raise ValueError("GSL library not loaded")
        np_array = np.zeros(size, dtype=complex)
        for i in range(size):
            np_array[i] = complex(gsl_vector.data[i * 2], gsl_vector.data[i * 2 + 1])
