    class GSLMatrix:
        def __init__(self, rows, cols):
            self.rows = rows
            self.cols = cols
            self.matrix = (ctypes.c_float * rows * cols)()

        def get_pointer(self):
            return ctypes.cast(self.matrix, ctypes.POINTER(ctypes.c_float))

    # Create a new instance of the GSLMatrix class for the input matrix
    gsl_matrix = GSLMatrix(len(matrix), len(matrix[0]))

    # Copy the Python list to the GSLMatrix instance
    for i in range(gsl_matrix.rows):
        for j in range(gsl_matrix.cols):
            gsl_matrix.matrix[i * gsl_matrix.cols + j] = matrix[i][j]

    # Call the 'gsl_matrix_minmax_index' function from the GSL library
    minmax_indices = gsl.gsl_matrix_minmax_index(gsl_matrix)

    # Extract the row and column indices of the minimum and maximum elements
    minimum_row = minmax_indices[0]
    minimum_column = minmax_indices[1]
    maximum_row = minmax_indices[2]
    maximum_column = minmax_indices[3]

    # Return a tuple of the row and column indices
    return (minimum_row, minimum_column, maximum_row, maximum_column)

