    gsl_linalg_LU_decomp_ptr.argtypes = [POINTER(GSLMatrix)]
    gsl_linalg_LU_decomp_ptr.restype = None

    # Allocate and initialize input matrix, permutation vector, and signum variable
    cmatrix = GSLMatrix(2)
