class GSLMatrix:
    def __init__(self, nrows, ncols=1):
        self.nrows = nrows
        self.ncols = ncols
        self.data = np.zeros((nrows, ncols), dtype=np.float64)

    def GetNrows(self):
        return self.nrows

    def GetNcols(self):
        return self.ncols

    def SetArray(self, arr):
        if len(arr) != self.GetNrows() * self.GetNcols():
            raise ValueError("Invalid array size")
        self.data = np.array(arr).reshape((self.GetNrows(), self.GetNcols()))

    def GetArray(self):
        return self.data.flatten().tolist()

class GSLPermutation:
    def __init__(self, size=1):
        self.size = size
        self.data = np.zeros(size, dtype=np.int)

    def GetSize(self):
        return self.size

    def SetArray(self, arr):
        if len(arr) != self.GetSize():
            raise ValueError("Invalid array size")
        self.data = np.array(arr).reshape((self.GetSize()))

    def GetArray(self):
        return self.data.flatten().tolist()

