class gsl_permutation(ctypes.Structure):
    _fields_ = [("data", ctypes.POINTER(ctypes.c_size_t)), ("size", ctypes.c_size_t)]

def create_permutation(n):
    permutation = gsl_permutation()
    status = gsl.gsl_permutation_calloc(ctypes.byref(permutation), n)
    if status:
        return []
    try:
        for i in range(n):
            permutation.data[i] = ctypes.c_size_t(i)
    finally:
        gsl.gsl_permutation_free(ctypes.byref(permutation))
    return list(permutation.data[:permutation.size])

def main():
    n = int(input())
    permutation = create_permutation(n)
    print(permutation)

