        self.func = func

    def __call__(self, x, params):
        return self.func(x, params)

def integrate_function(f, a, b, epsabs, epsrel, limit):
    result = gsl.gsl_integration_qags(GSLFunction(f), a, b, epsabs, epsrel, limit)
    return (result.val, result.err)

