    # define the function to integrate
    def my_function(x, params):
        a, b = params
        return (b-a)*x**2/2 + a*x + b

    # integrate the function from 0 to 1 with absolute and relative error tolerance of 1e-8 and workspace limit of 100
    integral, error = integrate_function(my_function, 0, 1, 1e-8, 1e-8, 100)

    # free the workspace to avoid memory leaks
    free_workspace()

    return json.dumps({"Candidate_solution": integral})

