    def __iter__(self):
        return iter(self.get())

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.matrix = (GSLVector * cols)()
        for i in range(cols):
            self.matrix[i] = GSLVector(rows)
    def get(self):
        result = []
        for col in self.matrix:
            result.append(list(col))
        return result
    def set(self, value):
        for i, row in enumerate(value):
            for j, val in enumerate(row):
                self.matrix[j].vector[i] = val
    def __iter__(self):
        return iter(self.get())

