def sort_eigenvalues_eigenvectors(eigenvalues, eigenvectors, sort_type):
    # Load C function from GSL library
    gsl_eigen_symmv_sort = gsl.gsl_eigen_symmv_sort
    gsl_eigen_symmv_sort.argtypes = [ctypes.POINTER(GSLVector), ctypes.POINTER(GSLMatrix)]
    gsl_eigen_symmv_sort.restype = None

    # Convert input to C types
    size = len(eigenvalues)
    eigenvalues_c = (ctypes.c_double * size)(*eigenvalues)
    eigenvectors_c = GSLMatrix(size, size)
    for i in range(size):
        for j in range(size):
            eigenvectors_c[i][j] = eigenvectors[i][j]

    # Call C function to sort eigenvalues and eigenvectors
    gsl_eigen_symmv_sort(eigenvalues_c, ctypes.pointer(eigenvectors_c))

    # Convert output back to Python types
    sorted_eigenvalues = list(eigenvalues_c)
    sorted_eigenvectors = [[list(col) for col in row] for row in eigenvectors_c]

    return sorted_eigenvalues, sorted_eigenvectors

