    _fields_ = [("data", ctypes.POINTER(ctypes.c_double)), ("size1", ctypes.c_int), ("size2", ctypes.c_int)]

def list_to_gsl_matrix(matrix: List[List[complex]]) -> GSLMatrix:
    # Convert nested list of complex numbers to GSL matrix
    size1 = len(matrix)
    size2 = len(matrix[0]) if size1 > 0 else 0
