            raise TypeError("Expected argument of type POINTER(gsl_matrix), got {}".format(type(value)))
        self._matrix = value

    def __repr__(self):
        return "GSLMatrix({}, {})".format(self.rows, self.cols)

def create_and_manipulate_matrix(rows=0, cols=0):
    matrix = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(min(rows, cols)):
        for j in range(min(rows, cols)):
            if rows > cols:
                set_element(matrix, i, j, i+1)
            else:
                set_element(matrix, i, j, j+1)
    return matrix

def set_element(matrix, row, col, value):
