class RingBuf:
    def __init__(self, size):
        self.size = size
        self.head = 0
        self.tail = 0
        self.buf = [None] * self.size

    def insert(self, values):
        for value in values:
            self.buf[self.head] = value
            self.head = (self.head + 1) % self.size
            if self.head == self.tail:
                self.tail = (self.tail + 1) % self.size

    def copy_to_list(self):
        return self.buf[self.tail:self.head]

def initialize_ringbuf(size):
    return RingBuf(size)

def insert_into_ringbuf(ringbuf, values):
    ringbuf.insert(values)

