def cholesky_decomp(matrix):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl_matrix = GSLMatrix(matrix)
    status = gsl.gsl_linalg_cholesky_decomp(gsl_matrix.matrix)
    if isnan(status):
        raise ValueError("Input matrix is not positive definite.")
    return [[gsl_matrix.matrix[i][j] for j in range(len(gsl_matrix.matrix))] for i in range(len(gsl_matrix.matrix))]

